LEVEL = 1
CFG = {1: ["a", "a", "b"], 2: ["a"] * 5 + ["b"] * 2, 3: ["a"] * 12}
LIMIT = 10
use = {}
for k in CFG[LEVEL]:
    use[k] = use.get(k, 0) + 1
for k, v in use.items():
    print("key", k, "usage %d/%d ->" % (v, LIMIT), "ok" if v <= LIMIT else "OVER QUOTA")

